import client from "../client";

const hospitalsOpenAction = (data) => {
  return client.post("/hospitals/open", data);
};
const hospitalStaffAction = (data) => {
  return client.post("/hospitals/staff", data);
};
const hospitalInpatientAction = (data) => {
  return client.post("/hospitals/inpatient", data);
};

export default {
  hospitalsOpenAction,
  hospitalStaffAction,
  hospitalInpatientAction
};
