import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
  CustomTextArea,
} from "../../../components";
import { useFormik } from "formik";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import "dayjs/locale/en-gb";
import { useDispatch } from "react-redux";
import { getLoggedInUser } from "../../../helpers/authUtils";

import useApi from "../../../hooks/useApi";
import { useStateContext } from "../../../contexts/ContextProvider";
import frequenciesApi from "../../../api/drugs/frequenciesApi";
import { Modal } from "antd";
import hospitalsApi from "../../../api/hospitals/hospitalsApi";
import routesApi from "../../../api/drugs/routesApi";
import departmentsApi from "../../../api/departmentsApi";

export default function DepartmentFormModal({
  openDepartmentFormModal,
  setopenDepartmentFormModal,
  selectedDepartment,
  setselectedDepartment,
  setUpdated,
  updated
}) {
  const dispatch = useDispatch();
  const [user, setUser] = useState();
  const [errors, setErrors] = useState();
  const { currentColor, loggedInUser } = useStateContext();

  //Retrieve frequencies
  const [frequencies, setFrequencies] = useState([]);
  const getFrequenciesApi = useApi(frequenciesApi.frequenciesAction);
  const getFrequencies = async () => {
    await getFrequenciesApi.request({
      action: "GetFrequencies",
    });
  };

  const [routes, setroutes] = useState([]);
  const getRoutesApi = useApi(routesApi.routesAction);
  const getRoutes = async () => {
    await getRoutesApi.request({
      action: "GetRoutes",
    });
  };

  useEffect(() => {
    if (getRoutesApi.data && getRoutesApi.data.length) {
      setroutes(
        getRoutesApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }
  }, [getRoutesApi.data]);

  useEffect(() => {
    if (user != null) {
      getFrequencies();
      getRoutes();
    }
  }, [user]);

  useEffect(() => {
    if (getFrequenciesApi.data && getFrequenciesApi.data.length) {
      setFrequencies(
        getFrequenciesApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }
    console.log("counties", frequencies);
  }, [getFrequenciesApi.data]);

  useEffect(() => {
    setUser(getLoggedInUser());
  }, []);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const departmentActionApi = useApi(departmentsApi.departmentsAction);
  const handleDepartmentAction = async (data) => {
    await departmentActionApi.request(data);
  };

  useEffect(() => {
    if (departmentActionApi.data) {
      if (departmentActionApi.data.department) {
        toast.success(departmentActionApi.data.response_message);
        setUpdated(true)
        setopenDepartmentFormModal(false)
      } else {
        toast.error(departmentActionApi.data.response_message);
      }
    }
    console.log("departmentActionApi.data", departmentActionApi.data)
  }, [departmentActionApi.data]);



  const formik = useFormik({
    initialValues: {
      title: selectedDepartment ? selectedDepartment.title : "",
      description: selectedDepartment ? selectedDepartment.description : "",
      department_type: selectedDepartment ? { label: selectedDepartment.department_type, value: selectedDepartment.department_type } : "",

    },

    validationSchema: Yup.object({
      title: Yup.string().required("Title is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action
      let data = null;
      console.log("VALZ", values)

      if (selectedDepartment) {
        data = {
          action: "UpdateDepartment",
          department: selectedDepartment.id,
          title: values.title,
          description: values.description,
          department_type: values.department_type.value,
        };
      } else {
        data = {
          action: "CreateDepartment",
          title: values.title,
          description: values.description,
          department_type: values.department_type.value,

        };
      }

      handleDepartmentAction(data);

      resetForm();
    },
  });

  useEffect(() => {
    console.log("formik", formik.errors);
  }, [formik]);

  const handleOk = () => {
    setopenDepartmentFormModal(false);
  };
  const handleCancel = () => {
    setopenDepartmentFormModal(false);
  };

  return (
    <div className=" max-w-fit min-w-fit">
      <ToastContainer theme="colored" position="bottom-center" />
      <Modal
        width={600}
        className="w-full text-center capitalize"
        title={
          selectedDepartment
            ? "EDIT " + selectedDepartment.title
            : "ADD NEW DEPARTMENT"
        }
        open={openDepartmentFormModal}
        onOk={handleOk}
        onCancel={handleCancel}
        closeIcon={true}
        closable={false}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full"
        >
          <CustomFormItem
            touched={formik.touched.title}
            error={formik.errors.title}
            className="w-full"
          >
            <CustomInput
              className="uppercase"
              id="title"
              name="title"
              required={true}
              onChange={formik.handleChange}
              placeholder="Enter title"
              label="Enter title"
              size="large"
              type="text"
              value={formik.values.title}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.department_type}
            error={formik.errors.department_type}
          >
            <CustomSelectReactSelect
              name="department_type"
              id="department_type"
              label="Select department type"
              size="large"
              onChange={(e) => formik.setFieldValue("department_type", e)}
              value={formik.values.department_type}
              placeholder="Select department type"
              options={[
                { value: "CLINIC", label: "CLINIC" },
                { value: "LABORATORY", label: "LABORATORY" },
                { value: "NUTRITION", label: "NUTRITION" },
                { value: "PHYSIOTHERAPY", label: "PHYSIOTHERAPY" },
                { value: "PHARMACY", label: "PHARMACY" },
                { value: "RADIOLOGY", label: "RADIOLOGY" },
                { value: "OUTPATIENT", label: "OUTPATIENT" },
                { value: "OTHER", label: "OTHER" },
                { value: "WARD", label: "WARD" },
              ]}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.description}
            error={formik.errors.description}
            className="w-full"
          >
            <CustomTextArea
              rows={2}
              id="description"
              name="description"
              onChange={formik.handleChange}
              placeholder="Any description"
              label="Any description"
              size="large"
              type="text"
              value={formik.values.description}
            />
          </CustomFormItem>

          <div className="w-full items-center mt-2">
            <Button
              style={{ background: currentColor }}
              className="w-36 rounded-md"
              color="primary"
              type="submit"
            >
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
