import React, { useEffect, useState } from "react";
import DepartmentsTable from "./DepartmentsTable";

import useApi from "../../../hooks/useApi";
import { useNavigate, useParams } from "react-router-dom";
import DepartmentFormModal from "./DepartmentFormModal";
import departmentsApi from "../../../api/departmentsApi";
import { Loading } from "../../../components";
import { useStateContext } from "../../../contexts/ContextProvider";

const columns = [
  { name: "Title", uid: "title" },
  { name: "Description", uid: "description" },
  { name: "Actions", uid: "actions" },
];

function DepartmentsList() {
  const [openDepartmentFormModal, setopenDepartmentFormModal] = useState(false);
  const [user, setUser] = useState();
  const navigate = useNavigate();
  const [selectedDepartment, setselectedDepartment] = useState();
  const [departments, setDepartments] = useState([]);
  const [data, setdata] = useState([]);
  const [modalTitle, setmodalTitle] = useState("");
  const [updated, setUpdated] = useState(false);

  const getDepartmentsActionsApi = useApi(departmentsApi.departmentsAction);

  const { loggedInUser } = useStateContext();

  const getDepartments = async (data) => {
    console.log("idee", data);
    await getDepartmentsActionsApi.request({
      action: "GetEntityDepartments",
      entity: data,
    });
  };

  useEffect(() => {
    if (getDepartmentsActionsApi.data) {
      if (getDepartmentsActionsApi.data.length) {
        setDepartments(getDepartmentsActionsApi.data);
      }
    }
  }, [getDepartmentsActionsApi.data]);

  useEffect(() => {
    if (loggedInUser !== null && loggedInUser.entity_id !== null) {
      getDepartments(loggedInUser.entity_id);
    }
    console.log("loggedInUser", loggedInUser);
  }, []);

  useEffect(() => {
    setdata(departments);
  }, [departments]);

  const handleEditAction = (item) => {
    setopenDepartmentFormModal(true);
    setselectedDepartment(item);
    setmodalTitle(`Edit ${item.title}`);
    setUpdated(false)
  };

  const handleAddAction = () => {
    setopenDepartmentFormModal(true);
    setmodalTitle("Add new body system");
    setselectedDepartment(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/systems/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    console.log("Item", item);
    navigate(`/systems/delete/${item.id}`);
  };

  useEffect(() => {
    if (getDepartmentsActionsApi.data && getDepartmentsActionsApi.data.length) {
      setDepartments(getDepartmentsActionsApi.data);
    }
    console.log("getDepartmentsActionsApi.data", getDepartmentsActionsApi.data);
  }, [getDepartmentsActionsApi.data]);

  useEffect(() => {
    if (updated === true) {
      if (loggedInUser !== null && loggedInUser.entity_id !== null) {
        getDepartments(loggedInUser.entity_id);
      }
    }
  }, [updated]);

  //Filtering data
  useEffect(() => {
    setdata(departments);
  }, [departments]);

  const handleFilter = (e) => {
    const search_param = e;
    if (
      departments &&
      departments.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        departments.filter((x) => x.title.toLowerCase().includes(search_param))
      );
    } else {
      setdata(departments);
    }
  };

  return getDepartmentsActionsApi.loading ? (
    <Loading loading={departmentsApi.loading} />
  ) : (
    <div className="mt-16 md:mt-2">
      {openDepartmentFormModal && (
        <DepartmentFormModal
          openDepartmentFormModal={openDepartmentFormModal}
          setopenDepartmentFormModal={setopenDepartmentFormModal}
          selectedDepartment={selectedDepartment}
          updated={updated}
          setselectedDepartment={setselectedDepartment}
          setUpdated={setUpdated}
          modalTitle={modalTitle}
        />
      )}
      <DepartmentsTable
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
      />
    </div>
  );
}

export default DepartmentsList;
